package com.example.obliviondescent;

/**
 * An enemy template generated by Gemini AI.
 * Applied to an existing enemy via Enemy.applyTemplate() to override
 * name, colour and HP/DMG multipliers without touching the base logic.
 */
public class EnemyTemplate {
    /** Custom display name for the enemy. */
    public String name;
    /** AI description of the enemy (reserved for future use). */
    public String description;
    /** Enemy body colour. */
    public int color;
    /** HP multiplier applied on top of the floor-scaled base HP. */
    public float hpMultiplier;
    /** Damage multiplier applied on top of the floor-scaled base damage. */
    public float dmgMultiplier;

    /**
     * Creates a new AI-generated enemy template.
     * @param name custom display name
     * @param description AI description
     * @param color enemy body colour
     * @param hpMultiplier HP multiplier
     * @param dmgMultiplier damage multiplier
     */
    public EnemyTemplate(String name, String description,
                         int color, float hpMultiplier, float dmgMultiplier) {
        this.name        = name;
        this.description = description;
        this.color       = color;
        this.hpMultiplier = hpMultiplier;
        this.dmgMultiplier = dmgMultiplier;
    }
}